import {defineReactElement,ThreeCanvas,MotionTarget} from '@motiframe/authoring';
import {create} from './scene';
import {during} from './motion';
const manifest={
  "id": "title",
  "revision": 2,
  "kind": "react",
  "moduleHash": "",
  "propsSchema": {
    "type": "object",
    "properties": {
      "text": {
        "type": "string"
      },
      "fontSize": {
        "type": "number"
      },
      "fontWeight": {
        "type": "number"
      },
      "fontFamily": {
        "type": "string"
      },
      "color": {
        "type": "string"
      },
      "width": {
        "type": "number"
      },
      "height": {
        "type": "number"
      }
    }
  },
  "targets": [
    {
      "key": "root",
      "channels": [
        "x",
        "y",
        "z",
        "scaleX",
        "scaleY",
        "rotateX",
        "rotateY",
        "rotateZ",
        "opacity",
        "clipProgress",
        "props.text"
      ],
      "coordinateSpace": "local"
    },
    {
      "key": "caption",
      "channels": [
        "opacity"
      ],
      "coordinateSpace": "local"
    }
  ],
  "slots": [],
  "assets": []
};
export default defineReactElement(manifest,({props,frame})=>{
 const t=frame.tick/240000;
 const firstRead=during(t,0.62,0.84)*(1-during(t,3.8,4.10));
 const inheritedRead=during(t,4.15,4.40);
 return <div style={{position:'relative',width:960,height:300}}>
  <ThreeCanvas frame={frame} width={960} height={300} create={create}/>
  <MotionTarget targetKey="caption"><div style={{position:'absolute',left:0,top:28,width:430,fontSize:44,fontFamily:String(props.fontFamily??'sans-serif'),color:String(props.color??'#ffffff'),opacity:Math.max(firstRead,inheritedRead),transform:'translateY('+((1-firstRead)*(1-inheritedRead)*12)+'px)'}}>
   {String(props.text??'Preparation. Release. Response.')}
  </div></MotionTarget>
 </div>;
});

