import {Scene,PerspectiveCamera,BoxGeometry,MeshBasicMaterial,Mesh} from 'three';
import {during} from './motion';
export function create({width,height}){
 const scene=new Scene();
 const camera=new PerspectiveCamera(36,width/height,0.1,100);camera.position.set(0,0,6);
 const actor=new Mesh(new BoxGeometry(1.15,1.15,1.15),new MeshBasicMaterial({color:'#bcf77b'}));scene.add(actor);
 return {scene,camera,update(frame){
  const t=frame.tick/240000;
  const prepare=during(t,0,0.28),release=during(t,0.28,0.48),response=during(t,0.48,0.82);
  const first=during(t,1.55,1.72),second=during(t,1.9,2.02),accent=during(t,2.35,2.60);
  const handoff=during(t,3.8,4.3);
  actor.position.set(-1.4-0.18*prepare+2.2*release-0.1*response+0.8*handoff,0,0);
  actor.scale.set(1-0.35*prepare+0.35*release+3.2*handoff,1+0.18*prepare-0.18*release+3.2*handoff,1+3.2*handoff);
  actor.rotation.set(0.12*release,0.7*release+0.28*first+0.28*second+1.1*accent,0.12*(release-response));
  const cameraLag=during(t,0.54,0.90);camera.position.set(0.22*cameraLag,0.05*cameraLag,6-0.4*during(t,2.48,2.82));camera.lookAt(0,0,0);
 }};
}

